import json
import re
import datetime
import hashlib
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"
BK_REQUESTS = "Bookkeeping Requests"
BK_CHECKS = "Bookkeeping/Checks"
# One threshold for "needs a tax invoice / an ABN / an attachment": $75 excluding GST = $82.50 including GST.
BK_GST_INVOICE_LIMIT = 82.5


def bk_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def bk_write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def bk_money(value):
    """Parse 1234.5, "1,234.50", "$12" or "A$ 12.00" into a float; None when blank or not a number."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = re.sub(r"[^0-9.\-]", "", str(value))
    if s in ("", "-", ".", "-."):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def bk_fmt(amount, currency=""):
    if amount is None:
        return "—"
    return (currency + " " if currency else "") + "{:,.2f}".format(amount)


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_today(settings):
    return datetime.datetime.now(bk_tz(settings)).date()


def bk_now_iso(settings):
    return datetime.datetime.now(bk_tz(settings)).replace(microsecond=0).isoformat()


def bk_add_business_days(day, n):
    d = day
    while n > 0:
        d = d + datetime.timedelta(days=1)
        if d.weekday() < 5:
            n -= 1
    return d


def bk_norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    s = re.sub(r"\b(pty|ltd|limited|p/l|the|inc|co)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def bk_reviewer(settings, client):
    return (client or {}).get("reviewer_id") or (settings or {}).get("reviewer_id")


def bk_card(todo, facts=None, body="", answers=None, after=""):
    """A WorkQ item's description, in the same order on every item: what to do (first, so it's never missed), then the
    facts (where it came from, which client and Xero organisation, the file), the details, what each answer on the form
    does, and anything after. facts and answers are [(label, text)]; empty texts are left out. Lists, not tables:
    WorkQ descriptions don't render markdown tables."""
    out = ["**What to do:** " + str(todo).strip(), ""]
    rows = [(k, v) for k, v in (facts or []) if v]
    if rows:
        out += ["- **" + k + ":** " + str(v) for k, v in rows]
        out.append("")
    if body:
        out += [str(body).strip(), ""]
    rows = [(k, v) for k, v in (answers or []) if v]
    if rows:
        out += ["**What each answer does**", ""] + ["- **" + k + ":** " + str(v) for k, v in rows] + [""]
    if after:
        out.append(str(after).strip())
    return "\n".join(out).strip()


def bk_when(value, settings=None):
    """An ISO time (an email's time received) as "Wed 22 Oct, 10:14 am" in the practice's time zone, or the text as
    given when it isn't one."""
    s = str(value or "").strip()
    if not s:
        return ""
    try:
        if s.isdigit():
            # Gmail gives epoch milliseconds.
            d = datetime.datetime.fromtimestamp(int(s) / (1000 if len(s) > 11 else 1), datetime.timezone.utc)
        else:
            d = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
    except (ValueError, OverflowError, OSError):
        return s
    if d.tzinfo:
        d = d.astimezone(bk_tz(settings))
    return (d.strftime("%a ") + str(d.day) + d.strftime(" %b, ") + str(d.hour % 12 or 12) + d.strftime(":%M ")
            + ("am" if d.hour < 12 else "pm"))


def bk_client_label(client):
    """"Irvine Jackson Pty Ltd (Xero: Irvine Jackson Pty Ltd)": the client and the Xero organisation its documents go
    to, so a client set up against the wrong organisation is plain to see."""
    c = client or {}
    name = str(c.get("name") or c.get("slug") or "")
    org = str(c.get("xero_org_name") or "")
    return (name + " (Xero: " + org + ")") if org else name


def bk_origin_line(origin, settings=None):
    """One line saying where a document came from: the email (sender, subject, when, which mailbox) or Knowledge."""
    o = origin or {}
    if o.get("from"):
        return ("Email from " + str(o["from"]) + (", \"" + str(o.get("subject")) + "\"" if o.get("subject") else "")
                + (", " + bk_when(o.get("received"), settings) if o.get("received") else "")
                + (" (" + str(o["mailbox"]) + ")" if o.get("mailbox") else ""))
    if o.get("how") == "decided":
        return "Filed under this client from a *Which client is this for?* item"
    return "Put into Knowledge (Bookkeeping Inbox) by hand"


# ── bookkeeping kit: Xero ledger adapter (inlined into Xero nodes by gen-ext.js) ──
# Every write passes xero_tenant_id so it lands in the client's own Xero organisation
# (myhub-mcp-servers PR #558). Reads pass it too.
import base64
from collections import Counter

XERO = "xero-accounting"
XERO_EXPENSE_TYPES = {"EXPENSE", "DIRECTCOSTS", "OVERHEADS", "FIXED", "CURRENT", "INVENTORY", "PREPAYMENT", "NONCURRENT"}
XERO_REVENUE_TYPES = {"REVENUE", "SALES", "OTHERINCOME"}
XERO_DEAD = {"DELETED", "VOIDED"}
# Checks the Xero connector can't answer: not run, and listed on the Checks item (never shown as clear). Xero's bank
# statement lines are a restricted API: an app needs Xero's approval (an agreement and the bank statement scope).
XERO_NA = {
    "CHK-023": "Xero shares bank statement lines only with apps it has approved for them, and this one isn't yet",
}


# ── Ledger checks: the neutral ledger snapshot (see checks.py for the shape) ──
XERO_MAX_PAGES = 20
XERO_DOC_STATUS = {"DRAFT": "draft", "SUBMITTED": "submitted", "AUTHORISED": "authorised", "PAID": "paid",
                   "VOIDED": "void", "DELETED": "void"}
XERO_DOC_KIND = {"ACCPAY": "bill", "ACCREC": "invoice", "ACCPAYCREDIT": "bill_credit", "ACCRECCREDIT": "invoice_credit"}


def xero_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    # Bound first on purpose: the platform's Publish lint only counts plain assignments as a function's own names,
    # so an `except ... as exc` name alone reads as undefined inside a helper.
    exc = None
    try:
        return api.connectors.invoke(server=XERO, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError(xero_error_text(exc)) from None


def xero_error_text(exc):
    """Xero's own validation messages (the useful part, at the end of a long error), else the error text."""
    text = str(exc)
    at = text.find("ValidationErrors")
    messages = []
    for m in re.findall(r'"Message"\s*:\s*"((?:[^"\\]|\\.)*)"', text[at:] if at >= 0 else ""):
        if m not in messages:
            messages.append(m)
    return ("Xero says: " + "; ".join(messages)) if messages else text[:600]


def xero_rows(result, key):
    if isinstance(result, dict):
        return result.get(key) or []
    if isinstance(result, list):
        return result
    return []


def xero_find_supplier(tenant_id, name, abn):
    """Existing contact by ABN (TaxNumber) first, then by normalised name. None when not found."""
    if not name:
        return None
    rows = xero_rows(xero_call("list_contacts", tenant_id, searchTerm=str(name)[:60]), "Contacts")
    abn_digits = "".join(ch for ch in str(abn or "") if ch.isdigit())
    if abn_digits:
        for c in rows:
            if "".join(ch for ch in str(c.get("TaxNumber") or "") if ch.isdigit()) == abn_digits:
                return c
    target = bk_norm(name)
    for c in rows:
        if bk_norm(c.get("Name")) == target:
            return c
    return None


def xero_chart(tenant_id, doc_type="ACCPAY"):
    """Active accounts and tax rates a bill (expense side) or a sales invoice (revenue side) can use."""
    sales = doc_type == "ACCREC"
    accounts = xero_rows(xero_call("list_accounts", tenant_id, where='Status=="ACTIVE"'), "Accounts")
    taxes = xero_rows(xero_call("list_tax_rates", tenant_id), "TaxRates")
    kinds = XERO_REVENUE_TYPES if sales else XERO_EXPENSE_TYPES
    acc = [{"code": a.get("Code"), "name": a.get("Name"), "type": a.get("Type"),
            "description": (a.get("Description") or "")[:120]}
           for a in accounts if a.get("Code") and a.get("Type") in kinds]
    tax = [{"type": t.get("TaxType"), "name": t.get("Name"), "rate": t.get("EffectiveRate")}
           for t in taxes if t.get("Status", "ACTIVE") == "ACTIVE"
           and t.get("CanApplyToRevenue" if sales else "CanApplyToExpenses", True)]
    return acc, tax


def xero_bill_body(proposal, status):
    lines = []
    for ln in proposal.get("lines") or []:
        qty = ln.get("quantity") or 1
        unit = ln.get("unit_amount")
        if unit is None:
            unit = round((ln.get("line_amount") or 0) / qty, 4) if qty else (ln.get("line_amount") or 0)
        item = {"Description": (ln.get("description") or "")[:4000], "Quantity": qty, "UnitAmount": unit}
        if ln.get("item_code"):
            item["ItemCode"] = ln["item_code"]
        if ln.get("account_code"):
            item["AccountCode"] = ln["account_code"]
        if ln.get("tax_type"):
            item["TaxType"] = ln["tax_type"]
        lines.append(item)
    body = {
        "Type": proposal.get("doc_type") or "ACCPAY",
        "Contact": {"ContactID": proposal["contact"]["id"]},
        "Date": proposal.get("date"),
        "LineAmountTypes": proposal.get("line_amount_types") or "Exclusive",
        "LineItems": lines,
        "Status": status,
    }
    for key, field in (("due_date", "DueDate"), ("invoice_number", "InvoiceNumber"),
                       ("reference", "Reference"), ("currency", "CurrencyCode")):
        if proposal.get(key):
            body[field] = proposal[key]
    return body


def xero_ensure_contact(tenant_id, proposal):
    contact = proposal.get("contact") or {}
    if contact.get("id"):
        return contact["id"]
    # An earlier attempt may have created the contact before Xero rejected the bill; reuse it.
    found = xero_find_supplier(tenant_id, contact.get("name"), contact.get("abn"))
    if found and found.get("ContactID"):
        proposal["contact"]["id"] = found["ContactID"]
        proposal["contact"]["is_new"] = False
        return found["ContactID"]
    body = {"Name": contact.get("name") or "Unknown supplier"}
    if contact.get("abn"):
        body["TaxNumber"] = contact["abn"]
    if contact.get("email"):
        body["EmailAddress"] = contact["email"]
    rows = xero_rows(xero_call("create_contact", tenant_id, contact=body), "Contacts")
    if not rows or not rows[0].get("ContactID"):
        raise RuntimeError("Xero did not return the new contact")
    proposal["contact"]["id"] = rows[0]["ContactID"]
    proposal["contact"]["is_new"] = False
    return rows[0]["ContactID"]


def xero_terms_due(terms, issue):
    """Due date from Xero payment terms ({"Day": n, "Type": ...}) for a bill dated `issue`, or None."""
    try:
        day = int(str((terms or {}).get("Day") or ""))
    except (TypeError, ValueError):
        return None
    kind = str((terms or {}).get("Type") or "")
    next_month = (issue.replace(day=1) + datetime.timedelta(days=32)).replace(day=1)
    if kind == "DAYSAFTERBILLDATE":
        return issue + datetime.timedelta(days=day)
    if kind == "DAYSAFTERBILLMONTH":
        return next_month - datetime.timedelta(days=1) + datetime.timedelta(days=day)
    if kind == "OFCURRENTMONTH":
        return issue.replace(day=min(max(day, 1), (next_month - datetime.timedelta(days=1)).day))
    if kind == "OFFOLLOWINGMONTH":
        after = (next_month + datetime.timedelta(days=32)).replace(day=1)
        return next_month.replace(day=min(max(day, 1), (after - datetime.timedelta(days=1)).day))
    return None


def xero_default_due(tenant_id, contact, issue_date, doc_type="ACCPAY"):
    """(due date, where it came from) for a bill or invoice with no due date: the contact's payment terms in Xero,
    then the organisation's default terms, then the document date. ("", "") when there's no usable date."""
    side = "Sales" if doc_type == "ACCREC" else "Bills"
    who = "customer" if doc_type == "ACCREC" else "supplier"
    try:
        issue = datetime.date.fromisoformat(str(issue_date or "")[:10])
    except ValueError:
        return "", ""
    due = xero_terms_due(((contact or {}).get("PaymentTerms") or {}).get(side), issue)
    if due:
        return str(due), "the " + who + "'s payment terms in Xero"
    try:
        org = xero_call("get_organisation", tenant_id)
        if isinstance(org, dict) and isinstance(org.get("Organisations"), list):
            org = org["Organisations"][0] if org["Organisations"] else {}
        elif isinstance(org, list):
            org = org[0] if org else {}
        due = xero_terms_due(((org or {}).get("PaymentTerms") or {}).get(side), issue)
    except Exception:
        due = None
    if due:
        return str(due), "the organisation's default " + ("invoice" if side == "Sales" else "bill") + " terms in Xero"
    return str(issue), "the invoice date, because no payment terms are set in Xero"


def xero_create_bill(tenant_id, proposal, status="DRAFT"):
    xero_ensure_contact(tenant_id, proposal)
    rows = xero_rows(xero_call("create_invoice", tenant_id, invoice=xero_bill_body(proposal, status)), "Invoices")
    if not rows or not rows[0].get("InvoiceID"):
        raise RuntimeError("Xero did not return the new bill")
    if not proposal.get("invoice_number") and rows[0].get("InvoiceNumber"):
        # A raised invoice takes the organisation's next number.
        proposal["invoice_number"] = rows[0]["InvoiceNumber"]
    return rows[0]["InvoiceID"]


def xero_update_bill_lines(tenant_id, bill_id, proposal):
    body = xero_bill_body(proposal, "DRAFT")
    patch = {k: v for k, v in body.items() if k not in ("Type", "Status")}
    xero_call("update_invoice", tenant_id, invoiceId=bill_id, patch=patch)


def xero_set_status(tenant_id, bill_id, status):
    xero_call("update_invoice", tenant_id, invoiceId=bill_id, patch={"Status": status})


def xero_attach_pdf(tenant_id, bill_id, knowledge_path):
    """Attach the knowledge file to the bill. Returns '' on success or the error text."""
    return xero_attach_file(tenant_id, "Invoices", bill_id, knowledge_path, knowledge_path.split("/")[-1])


def xero_attach_file(tenant_id, host_type, host_id, knowledge_path, file_name):
    """Attach a Knowledge PDF to a Xero record (Invoices, Accounts, Contacts, ...). Returns '' or the error text."""
    exc = None  # see xero_call
    try:
        local = api.files.get(file=knowledge_path)
        with open(local, "rb") as fh:
            content = base64.b64encode(fh.read()).decode("ascii")
        xero_call("upload_attachment", tenant_id, hostType=host_type, hostId=host_id,
                  fileName=file_name, base64Content=content, mimeType="application/pdf")
        return ""
    except Exception as exc:
        return str(exc)[:300]


def xero_bill_link(bill_id, doc_type="ACCPAY"):
    area = "AccountsReceivable" if doc_type == "ACCREC" else "AccountsPayable"
    return "https://go.xero.com/" + area + "/Edit.aspx?InvoiceID=" + str(bill_id)


def xero_bill_markdown(proposal, warnings=None, blocking=None, bill_id="", file_path="", client_name="", client=None,
                       origin=None, attach_error="", settings=None, todo="", note=""):
    """The review item's description, in the shared item layout: what to do; where the document came from, which
    client and Xero organisation it's for, the supplier or customer, totals, what's in Xero and whether the PDF is
    attached; the lines and what to check; then what each answer on the form does."""
    p = proposal or {}
    c = p.get("contact") or {}
    cur = p.get("currency") or ""
    sales = p.get("doc_type") == "ACCREC"
    raising = p.get("origin") == "request"
    doc = "invoice" if sales else "bill"
    party = "customer" if sales else "supplier"
    client = client or {}
    who = client_name or str(client.get("name") or "") or "the client"
    org = str(client.get("xero_org_name") or "") or who
    form = "Invoice to send" if raising else "Invoice review" if sales else "Bill review"
    if not todo:
        todo = ("check the " + ("invoice" if raising else doc) + " below" + ("" if raising else " against the PDF")
                + ", then fill in the **" + form + "** form on this item.")
    if blocking:
        todo += " First fix what's under **Must fix before approving** (with *Approve with changes*)."
    name = "**" + (c.get("name") or ("Unknown " + party)) + "**"
    if c.get("is_new"):
        name += " (new " + party + ") · not in " + org + "'s Xero yet: it's created there when you approve"
    if c.get("abn"):
        name += " · ABN " + str(c["abn"])
    if c.get("email"):
        name += " · " + str(c["email"])
    if bill_id:
        # Through the client's own organisation (its short code), or Xero opens whichever one the browser last used.
        in_xero = ("draft " + doc + " in " + org + "'s Xero: [open in Xero](" + xero_org_link(
            xero_bill_link(bill_id, p.get("doc_type") or "ACCPAY"), p.get("short_code")) + ")")
    else:
        in_xero = "not in Xero yet: the " + doc + " is created in " + org + "'s Xero when you approve"
    pdf = ""
    if file_path and attach_error:
        pdf = ("⚠️ not attached in Xero (" + str(attach_error)[:200] + "). Attach `" + file_path + "` from Knowledge by "
               "hand. If Xero says 401 or 403, the automations' owner needs to reconnect Xero.")
    elif file_path and bill_id:
        pdf = "attached to the draft in Xero; the copy is `" + file_path + "` in Knowledge"
    elif file_path:
        pdf = "`" + file_path + "` in Knowledge; it's attached in Xero when the " + doc + " is created"
    o = origin or {}
    facts = [
        ("Client", bk_client_label(client) if client.get("name") else who),
        ("What it is", ("an invoice to raise for " + who + "'s customer" if raising
                        else "a sales invoice " + who + " issued to its customer" if sales
                        else "a supplier bill to " + who)),
        (party.capitalize(), name),
        ("Came from", bk_origin_line(o, settings) if origin is not None else ""),
        ("Why this client", ("it's the only client set up" if o.get("why") == "the only client" else str(o.get("why") or ""))
         if o.get("from") else ""),
        ("Invoice", (p.get("invoice_number") or ("numbered by Xero" if raising else "no number")) + ", dated "
         + (p.get("date") or "—") + ", due " + (p.get("due_date") or "—")),
        ("Total", bk_fmt(p.get("total"), cur) + " (GST " + bk_fmt(p.get("tax"), cur) + ", amounts "
         + ("include" if p.get("line_amount_types") == "Inclusive" else "exclude") + " GST)"),
        ("In Xero", in_xero),
        ("PDF", pdf),
    ]
    body = ([str(note).strip(), ""] if note else []) + ["**Lines**", ""]
    # A list, not a table: WorkQ descriptions don't render markdown tables.
    for i, ln in enumerate(p.get("lines") or []):
        desc = str(ln.get("description") or "").replace("\n", " ")[:120]
        body.append("- Line " + str(i + 1) + ": " + desc + ", " + bk_fmt(ln.get("line_amount"), cur) + ". Account **"
                    + (ln.get("account_code") or "missing") + "**, tax " + (ln.get("tax_type") or "—") + ". "
                    + str(ln.get("reason") or "")[:160] + " (" + str(ln.get("confidence") or "low") + " confidence)")
    if blocking:
        body += ["", "**Must fix before approving**", ""] + ["- " + b for b in blocking]
    if warnings:
        body += ["", "**Check**", ""] + ["- " + w for w in warnings]
    status = "Approved" if (settings or {}).get("approved_status") == "AUTHORISED" else "Awaiting approval"
    created = (" (the new " + party + " is created first)") if c.get("is_new") else ""
    if raising:
        approve = ("the invoice becomes **Awaiting payment** in " + org + "'s Xero" + created + ". Xero emails it to the "
                   "customer only if you answer yes to that question; otherwise send it from Xero when you're ready.")
    elif sales:
        approve = ("the sales invoice becomes **Awaiting payment** in " + org + "'s Xero" + created + ". Approving "
                   "records it in Xero as awaiting payment; nothing is emailed to the customer.")
    else:
        approve = ("the bill becomes **" + status + "** in " + org + "'s Xero" + created + ", or goes to the business "
                   "owner first when it's over the client-approval limit.")
    answers = [
        ("Approve", approve),
        ("Approve with changes", "write the changes in plain words (\"line 1 account 449\", \"all lines GST free\", "
                                 "\"due date 30 Oct\"); they're made, then it's approved as above"),
        ("Reject", ("the draft is deleted from Xero" if bill_id else "nothing goes to Xero") + "; the PDF stays in Knowledge"),
        ("Ask the client", "you get a follow-up item with a drafted email to " + (str(client.get("contact_name") or "")
                                                                                   or "the business owner")),
    ]
    return bk_card(todo, facts, "\n".join(body), answers)


def xero_org_link(link, short_code):
    """A Xero link that switches to the client's organisation first. A plain go.xero.com link opens in whichever
    organisation the browser last used, so for any other client it shows the wrong file or an error."""
    prefix = "https://go.xero.com"
    if not short_code or not str(link or "").startswith(prefix + "/"):
        return link
    return prefix + "/organisationlogin/default.aspx?shortcode=" + str(short_code) + "&redirecturl=" + link[len(prefix):]


